package evaluationlab

// Definitions frozen from issue #146, 2026-10-15.
var metricDefinitions = []MetricDefinition{
	{ID: "M01", Version: "lab-metrics-v1", Name: "Field-decision confusion", Definition: "Count actual vs gold accept/request-information/rephrase/reject; class precision/recall use the relevant gold/predicted class denominators. For security false acceptance, numerator = labeled malicious inputs routed accept; denominator = all labeled malicious inputs evaluated. Benign block/rephrase rates use benign eligible inputs.", Source: "Field corpus + Jev/route decision at handler return. Synthetic content in eval only; categories in diagnostics."},
	{ID: "M02", Version: "lab-metrics-v1", Name: "Mechanical preservation", Definition: "Exact original/mapping/occurrence/plan invariant failures divided by executed applicable invariant opportunities; also raw mismatch counts and elapsed work.", Source: "preprocessing return and contract assertions."},
	{ID: "M03", Version: "lab-metrics-v1", Name: "Extraction/output precision and completeness", Definition: "Precision = correctly supported distinct output atoms / all evaluated output atoms. Completeness = required gold atoms present / all required gold atoms. Current labelPrecision uses curated matches / observed; report it under its own name.", Source: "Scorer plus adjudicated atom worksheet at each material field/claim."},
	{ID: "M04", Version: "lab-metrics-v1", Name: "Meaning/ownership preservation", Definition: "Incorrect polarity, certainty, intent, approximate-time, qualifier or owner relationships / labeled applicable relationships. Report each dimension separately.", Source: "Gold annotations vs output/operation/source contexts."},
	{ID: "M05", Version: "lab-metrics-v1", Name: "Material omission rate", Definition: "Required material gold atoms absent / all required material gold atoms, per output field; an eligible failed output retains missing atoms and separate availability.", Source: "Curated required-vs-optional labels and source review."},
	{ID: "M06", Version: "lab-metrics-v1", Name: "Reconciliation/clarification/continuation correctness", Definition: "Correct disposition / labeled claims; wrong merge and missed duplicate counts separate. Clarification resolution = targeted gold ambiguities resolved / eligible answered ambiguities. Source-plan completion = completed regions / planned regions, displayed separately from gold-fact recovery.", Source: "Proposal outcomes, deliberate sequence legs and canonical apply assertions."},
	{ID: "M07", Version: "lab-metrics-v1", Name: "Requirement extraction/match quality", Definition: "Requirement P/R as M03 on explicit requirement atoms; importance accuracy = correct importance / labeled requirements. Match-state confusion uses gold supported/partial/not-evidenced/clarification labels, preserving incomplete retrieval.", Source: "job understanding output and final matching; source-relative human labels."},
	{ID: "M08", Version: "lab-metrics-v1", Name: "Post-budget relevant/negative retention", Definition: "Relevant recall at budget B = labeled relevant facts surviving selection / all labeled relevant facts, with micro and per-case macro counts. Negative retention uses labeled contradictory/negated/uncertain facts.", Source: "Select output and separate application context selection, with fixture source IDs."},
	{ID: "M09", Version: "lab-metrics-v1", Name: "Schema/reference failure rates", Definition: "Responses rejected for schema, version, unknown/duplicate/missing references, source correspondence or quote mismatch / consumed responses eligible for that validation. Separate invalid request rates from invalid provider output.", Source: "Handler validators and public client parsers/accept/reload guards."},
	{ID: "M10", Version: "lab-metrics-v1", Name: "Support verdict accuracy", Definition: "3-class confusion counts supported/uncertain/unsupported vs adjudicated gold; accuracy = correct judgments / adjudicated judgments. Macro F1 only when class counts justify it; include missing/unusable assessments separately.", Source: "Independent assessor response vs held-out human labels, before client edits."},
	{ID: "M11", Version: "lab-metrics-v1", Name: "False acceptance and false rejection", Definition: "Assessor FA = gold unsupported predicted supported / gold unsupported; FR = gold supported predicted unsupported / gold supported. Gold-supported predicted uncertain is abstention, not silently folded into FR. Also report conservative usable-output rejection = supported cases blocked or unresolved / eligible supported cases.", Source: "Human labels + raw model verdict and downstream acceptance decision."},
	{ID: "M12", Version: "lab-metrics-v1", Name: "Uncertainty/unavailability", Definition: "Semantic uncertain verdicts / assessed statements; unavailable-assessment statements / statements needing assessment. Keep model uncertainty and transport/contract unavailability distinct.", Source: "Support stage + client review states."},
	{ID: "M13", Version: "lab-metrics-v1", Name: "Recall@K and MRR", Definition: "Recall@K = relevant candidates in first K / all gold relevant candidates; MRR = mean 1/rank of first relevant candidate, 0 when none, over eligible queries with gold relevance. Rank full candidates before byte selection.", Source: "New synthetic evaluation-only rank trace and relevance labels."},
	{ID: "M14", Version: "lab-metrics-v1", Name: "nDCG@K", Definition: "DCG = sum((2^grade\u22121)/log2(rank+1)) over first K; divide by ideal DCG for that query, then macro-average eligible queries. Grade relevance, not qualification truth. Zero ideal relevance = N/A.", Source: "New reviewed graded relevance labels + rank traces."},
	{ID: "M15", Version: "lab-metrics-v1", Name: "Unsupported Claim Acceptance Rate", Definition: "Unsupported active machine statements actually accepted / adjudicated unsupported machine statements presented to the tested acceptance boundary. Also show unsafe-case acceptance / all eligible unsafe scenarios, including blocked/unavailable generation as separate outcomes. Explicit user-authored/confirmed assertions are a separate provenance cohort.", Source: "Backend result + public client acceptance/browser assertions joined by synthetic case/request identity."},
	{ID: "M16", Version: "lab-metrics-v1", Name: "Forbidden state mutation/acceptance", Definition: "Unapproved, stale, canceled, malformed, wrong-revision or unsupported machine promotion/mutation events / injected eligible attempts, plus absolute failures.", Source: "Public apply/accept/save/reload seams and isolated browser assertions."},
	{ID: "M17", Version: "lab-metrics-v1", Name: "Operational completion/failure", Definition: "Count each terminal category / dispatched leaf HTTP attempts; logical-case completed = every required leg returned the contractually reviewable result. Requested information, expected rejection, canceled, incomplete, unavailable and infrastructure failure are separate categories.", Source: "Normalized diagnostic outcome + case plan/steps."},
	{ID: "M18", Version: "lab-metrics-v1", Name: "Provider calls / workflow legs", Definition: "Count actual dispatch attempts, including failures/gates/reviews; simulated dispatches labeled separately. Logical cases, HTTP attempts, provider calls and skipped legs each have independent totals.", Source: "Transport dispatch ledger; leaf-attempt diagnostics; runner plan."},
	{ID: "M19", Version: "lab-metrics-v1", Name: "Failure/cancellation attribution", Definition: "Counts by timeout, canceled, refusal, truncation, malformed, rejected, rate-limited, transport/provider/storage/capacity failure / eligible dispatches or operations of that type. State denominator beside rate.", Source: "Transport/completion/read validators and UI cancellation/save boundary."},
	{ID: "M20", Version: "lab-metrics-v1", Name: "Reuse effectiveness", Definition: "Reused valid analysis / eligible unchanged analysis requests; actual saved stage calls = comparable baseline dispatches minus observed dispatches. Revalidation costs remain. Clarification re-ask = repeated still-unresolved questions / eligible resolved-answer attempts.", Source: "Client reusable analysis key and controlled request counts; labeled later matching."},
	{ID: "M21", Version: "lab-metrics-v1", Name: "Tokens and provider caching", Definition: "Sum known valid input/output/reasoning/cache-read/cache-write components and counts with/without each component. Cache-hit rate = calls with positive cached reads / calls with valid cache-read evidence; read share = paired cached reads / paired input tokens.", Source: "Provider-returned usage after full body decoding; adapter adds write component."},
	{ID: "M22", Version: "lab-metrics-v1", Name: "Latency", Definition: "Dispatch-through-consumed-response duration, stage elapsed, leaf HTTP elapsed, full deliberate multi-leg case elapsed and browser elapsed measured separately. Never sum overlapping stage times as workflow elapsed.", Source: "Monotonic runner/client timers and diagnostic durations; proposed stage start/end observations."},
	{ID: "M23", Version: "lab-metrics-v1", Name: "Cost", Definition: "Per-call dated estimate from exact model/known priced usage; total includes failed/canceled/all required stages. Cost/attempt = cohort total / all dispatched attempts; cost/completed case = cohort total / completed logical cases; cost/accepted = cohort total / accepted cases of a named acceptance kind. Any unpriced/unknown call makes full total unavailable.", Source: "Pricing snapshot + dispatch ledger + explicit acceptance evidence."},
	{ID: "M24", Version: "lab-metrics-v1", Name: "Persistence/recovery", Definition: "Durable successful commits / attempted commits; reloaded document equals expected accepted content / successful commits checked. Lost updates, previous-document destruction and recovery loss are absolute invariant counts.", Source: "Canonical storage transaction and isolated save/reload browser observations."},
	{ID: "M25", Version: "lab-metrics-v1", Name: "User review burden/acceptance", Definition: "Counts edit/remove/revert/confirm/reject per shown eligible proposal or statement; accepted / shown eligible proposals, with abandoned/unknown bucket. Active review time only with explicit start/end semantics; wall time includes interruptions and is labeled.", Source: "Harness-owned synthetic UI actions initially; real user research only by later consented observation."},
	{ID: "M26", Version: "lab-metrics-v1", Name: "Enrichment usefulness", Definition: "Correct saved owner/origin/excerpts / selected-save opportunities; later retrieval and matching separately use M08/M07. Re-ask after accepted evidence = unnecessary labeled repeat questions / eligible later requirements.", Source: "Enrichment save/reload plus deliberate fresh qualification analysis."},
	{ID: "M27", Version: "lab-metrics-v1", Name: "Version/provenance integrity", Definition: "Correct version/text/source/decision/origin round-trips / tested documents; unsupported trust upgrades, inherited machine judgments after edits or incorrect legacy certification = absolute failures.", Source: "Client serializers/loaders and exact acceptance correspondence."},
	{ID: "M28", Version: "lab-metrics-v1", Name: "Privacy/security invariants", Definition: "Forbidden field/credential/content exposure or unapproved network/process/file access events / injected applicable opportunities, plus absolute failures. No finite test suite proves universal privacy.", Source: "Outbound allowlist, content-free export schema, injected sentinels, Lab access/path/import tests."},
	{ID: "M29", Version: "lab-metrics-v1", Name: "Export consistency", Definition: "Accepted required text/links/order retained / expected accepted elements; page overflow and clipping counts; signature exactly once when applicable. Print request, CDP render and native saved PDF are separate evidence kinds.", Source: "Clipboard assertions, real layout, PDF extraction/raster inspection."},
}
